typedef struct { pthread_mutex_t m; int state; } machine_t;

/* returns 1 when the caller now owns the running state, else balks (0) */
int machine_try_start(machine_t *w) {
    if (pthread_mutex_trylock(&w->m) != 0) return 0;      /* busy: balk */
    if (w->state != IDLE) { pthread_mutex_unlock(&w->m); return 0; }
    w->state = RUNNING;
    pthread_mutex_unlock(&w->m);
    return 1;
}
